import{_ as e,c as o,o as n,ae as a}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Styled List Element (Pro)","description":"Styled List Element (Pro)","frontmatter":{"title":"Styled List Element (Pro)","description":"Styled List Element (Pro)"},"headers":[],"relativePath":"guide/drag-drop-elements/styled-list.md","filePath":"guide/drag-drop-elements/styled-list.md"}'),l={name:"guide/drag-drop-elements/styled-list.md"};function i(r,t,s,d,c,h){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="styled-list-element-pro" tabindex="-1">Styled List Element (Pro) <a class="header-anchor" href="#styled-list-element-pro" aria-label="Permalink to &quot;Styled List Element (Pro)&quot;">​</a></h1><p>Ninja Tables Drag and Drop has a list element in the free version. It’s enough to create simple lists. But if you want a more attractive list, you will need more customization options. Ninja Tables offers an advanced element called “Styled List,” which is only available as a <strong>pro</strong> element. Let’s add a Styled List element to our Ninja Tables! Just drag and drop the element in your table, and that’s it. From the menu on the left side, you can see multiple customization options for this element.</p><h2 id="properties-of-styled-list" tabindex="-1"><strong>Properties of Styled List</strong> <a class="header-anchor" href="#properties-of-styled-list" aria-label="Permalink to &quot;**Properties of Styled List**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>General</td><td>Space Between Icon and Text</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Alignment</td><td>Left, Center, and Right</td></tr><tr><td>Text</td><td>Font Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Item Spacing</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Font Style</td><td>Bold, Italic &amp; Underline</td></tr><tr><td>Icon</td><td>Icon Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Icon Size</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Choose Icon</td><td>Upload from Computer</td></tr><tr><td></td><td>Icon Library</td><td>Selection from Library</td></tr></tbody></table><h3 id="general-options" tabindex="-1">General Options <a class="header-anchor" href="#general-options" aria-label="Permalink to &quot;General Options&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Styled-list-drag-and-drop-1024x550.png" alt="Styled list drag and drop"></p><ul><li><strong>Space Between Icon and Text:</strong> You can add space or gap between the Icons and List Items. By default, It is set to 0.</li><li>**Alignment: **You can align the Styled List to the left, right, or center. By default, it is set to Center.</li></ul><h3 id="text-options" tabindex="-1">Text Options <a class="header-anchor" href="#text-options" aria-label="Permalink to &quot;Text Options&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Styled-List-element-1024x560.png" alt="Styled List element"></p><ul><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: You can change the size of the text. By default, it is set to 15.</li><li><strong>Item Spacing</strong>: You can change the space vertically between list items. By default, it is set to 19.</li><li><strong>Font Style</strong>: You can change the Font Style orientations. Available options are <strong>Bold</strong>, <em>Italic</em>, and Underline.</li></ul><h3 id="icon-options" tabindex="-1">Icon Options <a class="header-anchor" href="#icon-options" aria-label="Permalink to &quot;Icon Options&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Stylied-list-icon-1024x516.png" alt="Stylied list icon"></p><ul><li><strong>Icon Color:</strong> You can change the color of the Icon. By default, it is set to Black.</li><li><strong>Icon Size:</strong> You can change the size of the Icon. By default, it is set to 15</li><li><strong>Choose Icon:</strong> You can upload your own image as an Icon to the table by uploading it from your computer or media dashboard.</li><li><strong>Icon Library:</strong> There are plenty of Icons to choose from in the Ninja Tables Styled List.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>A product table or a table that shows multiple features would look bland if you don&#39;t use any icons in the list. Styled list element in Ninja Tables drag and drop mode helps you create a dynamic data table. Let us know your thoughts and questions in the comment box.</p>',15)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
